","onUpdate":"
/* Get the dock array position*/
connection.__Pos=round((xFromVector(connection.position)-pillar_r)/stepX,0);
connection.__start=connection.__Pos;

connection.__w=other.width/stepX;

if(connection.start!=connection.__start||connection.width!=connection.__w){
for(i=connection.start;i<=connection.start+connection.width;i++){
set(fullHeightOccupations_front,i,0);
set(fullHeightOccupations_front_ext,i,0);
}
for(i=connection.__start;i<=connection.__start+connection.__w;i++){
set(fullHeightOccupations_front,i,idMarkedDoor);
set(fullHeightOccupations_front_ext,i,idMarkedDoor);
}
connection.start=connection.__start;
connection.width=connection.__w;
}
if(doubleDoors==0||(doubleDoors==1&&other.type==2)){
other.doublePossible=inner_w>6*AM_width;
}else{
other.doublePossible=false;
}

if(!gotMainDoor){
other.mainDoor=true;
gotMainDoor=true;
}
if(other.mainDoor&&preferredDoorType!=other.preferredType&&other.type!=preferredDoorType&&other.doublePossible){
/* clear entries so that conditions work during updates */
for(i=connection.start;i<=connection.start+connection.width;i++){
